1	/**
2	 * Phase Runner — core state machine driving the full phase lifecycle.
3	 *
4	 * Orchestrates: discuss → research → plan → execute → verify → advance
5	 * with config-driven step skipping, human gate callbacks, event emission,
6	 * and structured error handling per step.
7	 */
8	
9	import type {
10	  PhaseOpInfo,
11	  PhaseStepResult,
12	  PhaseRunnerResult,
13	  HumanGateCallbacks,
14	  PhaseRunnerOptions,
15	  PlanResult,
16	  SessionOptions,
17	  ParsedPlan,
18	  PhasePlanIndex,
19	  PlanInfo,
20	} from './types.js';
21	import { PhaseStepType, PhaseType, GSDEventType } from './types.js';
22	import type { GSDConfig } from './config.js';
23	import type { GSDTools } from './gsd-tools.js';
24	import type { GSDEventStream } from './event-stream.js';
25	import type { PromptFactory } from './phase-prompt.js';
26	import type { ContextEngine } from './context-engine.js';
27	import type { GSDLogger } from './logger.js';
28	import { runPhaseStepSession, runPlanSession } from './session-runner.js';
29	import { readFile } from 'node:fs/promises';
30	import { join } from 'node:path';
31	import { checkResearchGate } from './research-gate.js';
32	
33	// ─── Error type ──────────────────────────────────────────────────────────────
34	
35	export class PhaseRunnerError extends Error {
36	  constructor(
37	    message: string,
38	    public readonly phaseNumber: string,
39	    public readonly step: PhaseStepType,
40	    public readonly cause?: Error,
41	  ) {
42	    super(message);
43	    this.name = 'PhaseRunnerError';
44	  }
45	}
46	
47	// ─── Verification result enum ────────────────────────────────────────────────
48	
49	export type VerificationOutcome = 'passed' | 'human_needed' | 'gaps_found';
50	
51	// ─── PhaseRunner deps interface ──────────────────────────────────────────────
52	
53	export interface PhaseRunnerDeps {
54	  projectDir: string;
55	  tools: GSDTools;
56	  promptFactory: PromptFactory;
57	  contextEngine: ContextEngine;
58	  eventStream: GSDEventStream;
59	  config: GSDConfig;
60	  logger?: GSDLogger;
61	}
62	
63	// ─── PhaseRunner ─────────────────────────────────────────────────────────────
64	
65	export class PhaseRunner {
66	  private readonly projectDir: string;
67	  private readonly tools: GSDTools;
68	  private readonly promptFactory: PromptFactory;
69	  private readonly contextEngine: ContextEngine;
70	  private readonly eventStream: GSDEventStream;
71	  private readonly config: GSDConfig;
72	  private readonly logger?: GSDLogger;
73	
74	  constructor(deps: PhaseRunnerDeps) {
75	    this.projectDir = deps.projectDir;
76	    this.tools = deps.tools;
77	    this.promptFactory = deps.promptFactory;
78	    this.contextEngine = deps.contextEngine;
79	    this.eventStream = deps.eventStream;
80	    this.config = deps.config;
81	    this.logger = deps.logger;
82	  }
83	
84	  /**
85	   * Run a full phase lifecycle: discuss → research → plan → plan-check → execute → verify → advance.
86	   *
87	   * Each step is gated by config flags and phase state. Human gate callbacks
88	   * are invoked at decision points; when not provided, auto-approve is used.
89	   */
90	  async run(phaseNumber: string, options?: PhaseRunnerOptions): Promise<PhaseRunnerResult> {
91	    const startTime = Date.now();
92	    const steps: PhaseStepResult[] = [];
93	    const callbacks = options?.callbacks ?? {};
94	
95	    // ── Init: query phase state ──
96	    let phaseOp: PhaseOpInfo;
97	    try {
98	      phaseOp = await this.tools.initPhaseOp(phaseNumber);
99	    } catch (err) {
100	      throw new PhaseRunnerError(
101	        `Failed to initialize phase ${phaseNumber}: ${err instanceof Error ? err.message : String(err)}`,
102	        phaseNumber,
103	        PhaseStepType.Discuss,
104	        err instanceof Error ? err : undefined,
105	      );
106	    }
107	
108	    // Validate phase exists
109	    if (!phaseOp.phase_found) {
110	      throw new PhaseRunnerError(
111	        `Phase ${phaseNumber} not found on disk`,
112	        phaseNumber,
113	        PhaseStepType.Discuss,
114	      );
115	    }
116	
117	    const phaseName = phaseOp.phase_name;
118	
119	    // Emit phase_start
120	    this.eventStream.emitEvent({
121	      type: GSDEventType.PhaseStart,
122	      timestamp: new Date().toISOString(),
123	      sessionId: '',
124	      phaseNumber,
125	      phaseName,
126	    });
127	
128	    const sessionOpts: SessionOptions = {
129	      maxTurns: options?.maxTurnsPerStep ?? 50,
130	      maxBudgetUsd: options?.maxBudgetPerStep ?? 5.0,
131	      model: options?.model,
132	      cwd: this.projectDir,
133	    };
134	
135	    let halted = false;
136	
137	    // ── Step 1: Discuss ──
138	    if (!halted) {
139	      const shouldSkip = phaseOp.has_context || this.config.workflow.skip_discuss;
140	      if (shouldSkip && !(this.config.workflow.auto_advance && !phaseOp.has_context && !this.config.workflow.skip_discuss)) {
141	        this.logger?.debug(`Skipping discuss: has_context=${phaseOp.has_context}, skip_discuss=${this.config.workflow.skip_discuss}`);
142	      } else if (!phaseOp.has_context && !this.config.workflow.skip_discuss && this.config.workflow.auto_advance) {
143	        // AI self-discuss: auto-mode with no context — run a self-discuss session
144	        const result = await this.retryOnce('self-discuss', () => this.runSelfDiscussStep(phaseNumber, sessionOpts));
145	        steps.push(result);
146	
147	        // Re-query phase state to check if context was created
148	        try {
149	          phaseOp = await this.tools.initPhaseOp(phaseNumber);
150	        } catch {
151	          // If re-query fails, proceed with original state
152	        }
153	
154	        if (!phaseOp.has_context) {
155	          const decision = await this.invokeBlockerCallback(callbacks, phaseNumber, PhaseStepType.Discuss, 'No context after self-discuss step');
156	          if (decision === 'stop') {
157	            halted = true;
158	          }
159	        }
160	      } else if (!shouldSkip) {
161	        const result = await this.retryOnce('discuss', () => this.runStep(PhaseStepType.Discuss, phaseNumber, sessionOpts));
162	        steps.push(result);
163	
164	        // Re-query phase state to check if context was created
165	        try {
166	          phaseOp = await this.tools.initPhaseOp(phaseNumber);
167	        } catch {
168	          // If re-query fails, proceed with original state
169	        }
170	
171	        if (!phaseOp.has_context) {
172	          // No context after discuss — invoke blocker callback
173	          const decision = await this.invokeBlockerCallback(callbacks, phaseNumber, PhaseStepType.Discuss, 'No context after discuss step');
174	          if (decision === 'stop') {
175	            halted = true;
176	          }
177	        }
178	      }
179	    }
180	
181	    // ── Step 2: Research ──
182	    if (!halted) {
183	      if (!this.config.workflow.research) {
184	        this.logger?.debug('Skipping research: config.workflow.research=false');
185	      } else {
186	        const result = await this.retryOnce('research', () => this.runStep(PhaseStepType.Research, phaseNumber, sessionOpts));
187	        steps.push(result);
188	      }
189	    }
190	
191	    // ── Step 2.5: Research gate (#1602) ──
192	    // Check RESEARCH.md for unresolved open questions before planning
193	    if (!halted && phaseOp.has_research) {
194	      const gateResult = await this.checkResearchGate(phaseOp);
195	      if (!gateResult.pass) {
196	        const questionList = gateResult.unresolvedQuestions.join(', ');
197	        const error = `RESEARCH.md has unresolved open questions: ${questionList}`;
198	        this.logger?.warn(error, { phase: phaseNumber });
199	        const decision = await this.invokeBlockerCallback(callbacks, phaseNumber, PhaseStepType.Research, error);
200	        if (decision === 'stop') {
201	          halted = true;
202	        }
203	      }
204	    }
205	
206	    // ── Step 3: Plan ──
207	    if (!halted) {
208	      const result = await this.retryOnce('plan', () => this.runStep(PhaseStepType.Plan, phaseNumber, sessionOpts));
209	      steps.push(result);
210	
211	      // Re-query to check for plans
212	      try {
213	        phaseOp = await this.tools.initPhaseOp(phaseNumber);
214	      } catch {
215	        // Proceed with prior state
216	      }
217	
218	      if (!phaseOp.has_plans || phaseOp.plan_count === 0) {
219	        const decision = await this.invokeBlockerCallback(callbacks, phaseNumber, PhaseStepType.Plan, 'No plans created after plan step');
220	        if (decision === 'stop') {
221	          halted = true;
222	        }
223	      }
224	    }
225	
226	    // ── Step 3.5: Plan Check ──
227	    if (!halted && this.config.workflow.plan_check) {
228	      const planCheckResult = await this.retryOnce('plan-check', () => this.runPlanCheckStep(phaseNumber, sessionOpts));
229	      steps.push(planCheckResult);
230	
231	      // If plan-check failed, re-plan once then re-check once (D023)
232	      if (!planCheckResult.success) {
233	        this.logger?.info(`Plan check failed for phase ${phaseNumber}, re-planning once (D023)`);
234	
235	        // Re-run plan step with feedback
236	        const replanResult = await this.runStep(PhaseStepType.Plan, phaseNumber, sessionOpts);
237	        steps.push(replanResult);
238	
239	        // Re-check once
240	        const recheckResult = await this.runPlanCheckStep(phaseNumber, sessionOpts);
241	        steps.push(recheckResult);
242	
243	        if (!recheckResult.success) {
244	          this.logger?.warn(`Plan check failed again after re-plan for phase ${phaseNumber}. Proceeding with warning (D023).`);
245	        }
246	      }
247	    }
248	
249	    // ── Step 4: Execute ──
250	    if (!halted) {
251	      const executeResult = await this.retryOnce('execute', () => this.runExecuteStep(phaseNumber, sessionOpts));
252	      steps.push(executeResult);
253	    }
254	
255	    // ── Step 5: Verify ──
256	    if (!halted) {
257	      if (!this.config.workflow.verifier) {
258	        this.logger?.debug('Skipping verify: config.workflow.verifier=false');
259	      } else {
260	        // Verify has its own internal retry logic (gap closure). retryOnce only
261	        // retries on unexpected session throws, not on verification outcomes like gaps_found.
262	        const verifyResult = await this.retryOnce('verify', () => this.runVerifyStep(phaseNumber, sessionOpts, callbacks, options));
263	        steps.push(verifyResult);
264	
265	        // Check if verify resulted in a halt
266	        if (!verifyResult.success && verifyResult.error === 'halted_by_callback') {
267	          halted = true;
268	        }
269	      }
270	    }
271	
272	    // ── Step 6: Advance ──
273	    // Only advance if verify passed — never mark a phase complete when gaps were found.
274	    const verifyPassed = steps.every(s => s.step !== PhaseStepType.Verify || s.success);
275	    if (!halted && verifyPassed) {
276	      const advanceResult = await this.runAdvanceStep(phaseNumber, sessionOpts, callbacks);
277	      steps.push(advanceResult);
278	    } else if (!halted && !verifyPassed) {
279	      this.logger?.warn(`Skipping advance for phase ${phaseNumber}: verification found gaps`);
280	    }
281	
282	    const totalDurationMs = Date.now() - startTime;
283	    const totalCostUsd = steps.reduce((sum, s) => {
284	      const stepCost = s.planResults?.reduce((c, pr) => c + pr.totalCostUsd, 0) ?? 0;
285	      return sum + stepCost;
286	    }, 0);
287	    const success = !halted && steps.every(s => s.success);
288	
289	    // Emit phase_complete
290	    this.eventStream.emitEvent({
291	      type: GSDEventType.PhaseComplete,
292	      timestamp: new Date().toISOString(),
293	      sessionId: '',
294	      phaseNumber,
295	      phaseName,
296	      success,
297	      totalCostUsd,
298	      totalDurationMs,
299	      stepsCompleted: steps.length,
300	    });
301	
302	    return {
303	      phaseNumber,
304	      phaseName,
305	      steps,
306	      success,
307	      totalCostUsd,
308	      totalDurationMs,
309	    };
310	  }
311	
312	  // ─── Step runners ──────────────────────────────────────────────────────
313	
314	  /**
315	   * Retry a step function once on failure.
316	   * On first error/failure, logs a warning and calls the function once more.
317	   * Returns the result from the last attempt.
318	   */
319	  private async retryOnce<T extends PhaseStepResult>(label: string, fn: () => Promise<T>): Promise<T> {
320	    const result = await fn();
321	    if (result.success) return result;
322	
323	    // Don't retry verify outcomes (gaps_found, human_needed) — they have their own retry logic.
324	    if (result.error?.startsWith('verification_')) return result;
325	
326	    this.logger?.warn(`Step "${label}" failed, retrying once...`);
327	    return fn();
328	  }
329	
330	  /**
331	   * Run the plan-check step.
332	   * Loads the gsd-plan-checker agent definition, runs a Verify-scoped session,
333	   * and parses output for PASS/FAIL signals.
334	   */
335	  private async runPlanCheckStep(
336	    phaseNumber: string,
337	    sessionOpts: SessionOptions,
338	  ): Promise<PhaseStepResult> {
339	    const stepStart = Date.now();
340	
341	    this.eventStream.emitEvent({
342	      type: GSDEventType.PhaseStepStart,
343	      timestamp: new Date().toISOString(),
344	      sessionId: '',
345	      phaseNumber,
346	      step: PhaseStepType.PlanCheck,
347	    });
348	
349	    let planResult: PlanResult;
350	    try {
351	      // Load plan-checker agent definition (same pattern as PromptFactory.loadAgentDef)
352	      const agentDef = await this.promptFactory.loadAgentDef(PhaseType.Verify);
353	
354	      // Build prompt using Verify phase type for context resolution
355	      const contextFiles = await this.contextEngine.resolveContextFiles(PhaseType.Verify);
356	      let prompt = await this.promptFactory.buildPrompt(PhaseType.Verify, null, contextFiles);
357	
358	      // Supplement with plan-checker instructions
359	      prompt += '\n\n## Plan Checker Instructions\n\nYou are a plan checker. Review the plans for this phase and verify they are well-formed, complete, and achievable. If all plans pass, output "VERIFICATION PASSED". If any issues are found, output "ISSUES FOUND" followed by a description of each issue.';
360	
361	      planResult = await runPhaseStepSession(
362	        prompt,
363	        PhaseStepType.PlanCheck,
364	        this.config,
365	        sessionOpts,
366	        this.eventStream,
367	        { phase: PhaseType.Verify, planName: undefined },
368	      );
369	    } catch (err) {
370	      const durationMs = Date.now() - stepStart;
371	      const errorMsg = err instanceof Error ? err.message : String(err);
372	
373	      this.eventStream.emitEvent({
374	        type: GSDEventType.PhaseStepComplete,
375	        timestamp: new Date().toISOString(),
376	        sessionId: '',
377	        phaseNumber,
378	        step: PhaseStepType.PlanCheck,
379	        success: false,
380	        durationMs,
381	        error: errorMsg,
382	      });
383	
384	      return {
385	        step: PhaseStepType.PlanCheck,
386	        success: false,
387	        durationMs,
388	        error: errorMsg,
389	      };
390	    }
391	
392	    const durationMs = Date.now() - stepStart;
393	    // Parse plan-check outcome: success if the session succeeded (real output parsing would check for VERIFICATION PASSED / ISSUES FOUND)
394	    const success = planResult.success;
395	
396	    this.eventStream.emitEvent({
397	      type: GSDEventType.PhaseStepComplete,
398	      timestamp: new Date().toISOString(),
399	      sessionId: planResult.sessionId,
400	      phaseNumber,
401	      step: PhaseStepType.PlanCheck,
402	      success,
403	      durationMs,
404	      error: planResult.error?.messages.join('; ') || undefined,
405	    });
406	
407	    return {
408	      step: PhaseStepType.PlanCheck,
409	      success,
410	      durationMs,
411	      error: planResult.error?.messages.join('; ') || undefined,
412	      planResults: [planResult],
413	    };
414	  }
415	
416	  /**
417	   * Run the self-discuss step for auto-mode.
418	   * When auto_advance is true and no context exists, run an AI self-discuss
419	   * session that identifies gray areas and makes opinionated decisions.
420	   */
421	  private async runSelfDiscussStep(
422	    phaseNumber: string,
423	    sessionOpts: SessionOptions,
424	  ): Promise<PhaseStepResult> {
425	    const stepStart = Date.now();
426	
427	    this.eventStream.emitEvent({
428	      type: GSDEventType.PhaseStepStart,
429	      timestamp: new Date().toISOString(),
430	      sessionId: '',
431	      phaseNumber,
432	      step: PhaseStepType.Discuss,
433	    });
434	
435	    let planResult: PlanResult;
436	    try {
437	      const contextFiles = await this.contextEngine.resolveContextFiles(PhaseType.Discuss);
438	      let prompt = await this.promptFactory.buildPrompt(PhaseType.Discuss, null, contextFiles);
439	
440	      // Supplement with self-discuss instructions with pass cap
441	      const maxPasses = this.config.workflow.max_discuss_passes ?? 3;
442	      prompt += `\n\n## Self-Discuss Mode\n\nYou are the AI discussing decisions with yourself. No human is present. Identify 3-5 gray areas in the project scope, reason through each one, make opinionated choices, and write CONTEXT.md with your decisions.\n\n**CRITICAL: Single-pass only.** You MUST complete all decisions in ONE pass and write CONTEXT.md once. Do NOT re-read your own CONTEXT.md to find "gaps" and do additional passes. The maximum allowed passes is ${maxPasses} — if you have already written CONTEXT.md, you are DONE. Proceed to the next workflow step. Self-referential gap-finding loops waste resources without adding value.`;
443	
444	      planResult = await runPhaseStepSession(
445	        prompt,
446	        PhaseStepType.Discuss,
447	        this.config,
448	        sessionOpts,
449	        this.eventStream,
450	        { phase: PhaseType.Discuss, planName: undefined },
451	      );
452	    } catch (err) {
453	      const durationMs = Date.now() - stepStart;
454	      const errorMsg = err instanceof Error ? err.message : String(err);
455	
456	      this.eventStream.emitEvent({
457	        type: GSDEventType.PhaseStepComplete,
458	        timestamp: new Date().toISOString(),
459	        sessionId: '',
460	        phaseNumber,
461	        step: PhaseStepType.Discuss,
462	        success: false,
463	        durationMs,
464	        error: errorMsg,
465	      });
466	
467	      return {
468	        step: PhaseStepType.Discuss,
469	        success: false,
470	        durationMs,
471	        error: errorMsg,
472	      };
473	    }
474	
475	    const durationMs = Date.now() - stepStart;
476	    const success = planResult.success;
477	
478	    this.eventStream.emitEvent({
479	      type: GSDEventType.PhaseStepComplete,
480	      timestamp: new Date().toISOString(),
481	      sessionId: planResult.sessionId,
482	      phaseNumber,
483	      step: PhaseStepType.Discuss,
484	      success,
485	      durationMs,
486	      error: planResult.error?.messages.join('; ') || undefined,
487	    });
488	
489	    return {
490	      step: PhaseStepType.Discuss,
491	      success,
492	      durationMs,
493	      error: planResult.error?.messages.join('; ') || undefined,
494	      planResults: [planResult],
495	    };
496	  }
497	
498	  /**
499	   * Run a single phase step session (discuss, research, plan).
500	   * Emits step start/complete events and captures errors.
501	   */
502	  private async runStep(
503	    step: PhaseStepType,
504	    phaseNumber: string,
505	    sessionOpts: SessionOptions,
506	  ): Promise<PhaseStepResult> {
507	    const stepStart = Date.now();
508	
509	    this.eventStream.emitEvent({
510	      type: GSDEventType.PhaseStepStart,
511	      timestamp: new Date().toISOString(),
512	      sessionId: '',
513	      phaseNumber,
514	      step,
515	    });
516	
517	    let planResult: PlanResult;
518	    try {
519	      // Map step to PhaseType for prompt/context resolution
520	      const phaseType = this.stepToPhaseType(step);
521	      const contextFiles = await this.contextEngine.resolveContextFiles(phaseType);
522	      const prompt = await this.promptFactory.buildPrompt(phaseType, null, contextFiles);
523	
524	      planResult = await runPhaseStepSession(
525	        prompt,
526	        step,
527	        this.config,
528	        sessionOpts,
529	        this.eventStream,
530	        { phase: phaseType, planName: undefined },
531	      );
532	    } catch (err) {
533	      const durationMs = Date.now() - stepStart;
534	      const errorMsg = err instanceof Error ? err.message : String(err);
535	
536	      this.eventStream.emitEvent({
537	        type: GSDEventType.PhaseStepComplete,
538	        timestamp: new Date().toISOString(),
539	        sessionId: '',
540	        phaseNumber,
541	        step,
542	        success: false,
543	        durationMs,
544	        error: errorMsg,
545	      });
546	
547	      return {
548	        step,
549	        success: false,
550	        durationMs,
551	        error: errorMsg,
552	      };
553	    }
554	
555	    const durationMs = Date.now() - stepStart;
556	    const success = planResult.success;
557	
558	    this.eventStream.emitEvent({
559	      type: GSDEventType.PhaseStepComplete,
560	      timestamp: new Date().toISOString(),
561	      sessionId: planResult.sessionId,
562	      phaseNumber,
563	      step,
564	      success,
565	      durationMs,
566	      error: planResult.error?.messages.join('; ') || undefined,
567	    });
568	
569	    return {
570	      step,
571	      success,
572	      durationMs,
573	      error: planResult.error?.messages.join('; ') || undefined,
574	      planResults: [planResult],
575	    };
576	  }
577	
578	  /**
579	   * Run the execute step — uses phase-plan-index for wave-grouped parallel execution.
580	   * Plans in the same wave run concurrently via Promise.allSettled().
581	   * Waves execute sequentially (wave 1 completes before wave 2 starts).
582	   * Respects config.parallelization: false to fall back to sequential execution.
583	   * Filters out plans with has_summary: true (already completed).
584	   */
585	  private async runExecuteStep(
586	    phaseNumber: string,
587	    sessionOpts: SessionOptions,
588	  ): Promise<PhaseStepResult> {
589	    const stepStart = Date.now();
590	
591	    this.eventStream.emitEvent({
592	      type: GSDEventType.PhaseStepStart,
593	      timestamp: new Date().toISOString(),
594	      sessionId: '',
595	      phaseNumber,
596	      step: PhaseStepType.Execute,
597	    });
598	
599	    // Get the plan index from gsd-tools
600	    let planIndex: PhasePlanIndex;
601	    try {
602	      planIndex = await this.tools.phasePlanIndex(phaseNumber);
603	    } catch (err) {
604	      const durationMs = Date.now() - stepStart;
605	      const errorMsg = err instanceof Error ? err.message : String(err);
606	      this.eventStream.emitEvent({
607	        type: GSDEventType.PhaseStepComplete,
608	        timestamp: new Date().toISOString(),
609	        sessionId: '',
610	        phaseNumber,
611	        step: PhaseStepType.Execute,
612	        success: false,
613	        durationMs,
614	        error: errorMsg,
615	      });
616	      return {
617	        step: PhaseStepType.Execute,
618	        success: false,
619	        durationMs,
620	        error: errorMsg,
621	      };
622	    }
623	
624	    // Filter to incomplete plans only (has_summary === false)
625	    const incompletePlans = planIndex.plans.filter(p => !p.has_summary);
626	
627	    if (incompletePlans.length === 0) {
628	      const durationMs = Date.now() - stepStart;
629	      this.eventStream.emitEvent({
630	        type: GSDEventType.PhaseStepComplete,
631	        timestamp: new Date().toISOString(),
632	        sessionId: '',
633	        phaseNumber,
634	        step: PhaseStepType.Execute,
635	        success: true,
636	        durationMs,
637	      });
638	      return {
639	        step: PhaseStepType.Execute,
640	        success: true,
641	        durationMs,
642	        planResults: [],
643	      };
644	    }
645	
646	    const planResults: PlanResult[] = [];
647	
648	    // Sequential fallback when parallelization is disabled
649	    if (this.config.parallelization === false) {
650	      for (const plan of incompletePlans) {
651	        const result = await this.executeSinglePlan(phaseNumber, plan.id, sessionOpts);
652	        planResults.push(result);
653	      }
654	    } else {
655	      // Group incomplete plans by wave, sort waves numerically
656	      const waveMap = new Map<number, PlanInfo[]>();
657	      for (const plan of incompletePlans) {
658	        const existing = waveMap.get(plan.wave) ?? [];
659	        existing.push(plan);
660	        waveMap.set(plan.wave, existing);
661	      }
662	      const sortedWaves = [...waveMap.keys()].sort((a, b) => a - b);
663	
664	      for (const waveNum of sortedWaves) {
665	        const wavePlans = waveMap.get(waveNum)!;
666	        const wavePlanIds = wavePlans.map(p => p.id);
667	
668	        // Emit wave_start
669	        this.eventStream.emitEvent({
670	          type: GSDEventType.WaveStart,
671	          timestamp: new Date().toISOString(),
672	          sessionId: '',
673	          phaseNumber,
674	          waveNumber: waveNum,
675	          planCount: wavePlans.length,
676	          planIds: wavePlanIds,
677	        });
678	
679	        const waveStart = Date.now();
680	
681	        // Execute all plans in this wave concurrently
682	        const settled = await Promise.allSettled(
683	          wavePlans.map(plan => this.executeSinglePlan(phaseNumber, plan.id, sessionOpts)),
684	        );
685	
686	        // Map settled results to PlanResult[]
687	        let successCount = 0;
688	        let failureCount = 0;
689	        for (const outcome of settled) {
690	          if (outcome.status === 'fulfilled') {
691	            planResults.push(outcome.value);
692	            if (outcome.value.success) successCount++;
693	            else failureCount++;
694	          } else {
695	            failureCount++;
696	            planResults.push({
697	              success: false,
698	              sessionId: '',
699	              totalCostUsd: 0,
700	              durationMs: 0,
701	              usage: { inputTokens: 0, outputTokens: 0, cacheReadInputTokens: 0, cacheCreationInputTokens: 0 },
702	              numTurns: 0,
703	              error: {
704	                subtype: 'error_during_execution',
705	                messages: [outcome.reason instanceof Error ? outcome.reason.message : String(outcome.reason)],
706	              },
707	            });
708	          }
709	        }
710	
711	        // Emit wave_complete
712	        this.eventStream.emitEvent({
713	          type: GSDEventType.WaveComplete,
714	          timestamp: new Date().toISOString(),
715	          sessionId: '',
716	          phaseNumber,
717	          waveNumber: waveNum,
718	          successCount,
719	          failureCount,
720	          durationMs: Date.now() - waveStart,
721	        });
722	      }
723	    }
724	
725	    const durationMs = Date.now() - stepStart;
726	    const allSucceeded = planResults.every(r => r.success);
727	
728	    this.eventStream.emitEvent({
729	      type: GSDEventType.PhaseStepComplete,
730	      timestamp: new Date().toISOString(),
731	      sessionId: '',
732	      phaseNumber,
733	      step: PhaseStepType.Execute,
734	      success: allSucceeded,
735	      durationMs,
736	    });
737	
738	    return {
739	      step: PhaseStepType.Execute,
740	      success: allSucceeded,
741	      durationMs,
742	      planResults,
743	    };
744	  }
745	
746	  /**
747	   * Execute a single plan by ID within the execute step.
748	   */
749	  private async executeSinglePlan(
750	    phaseNumber: string,
751	    planId: string,
752	    sessionOpts: SessionOptions,
753	  ): Promise<PlanResult> {
754	    try {
755	      const phaseType = PhaseType.Execute;
756	      const contextFiles = await this.contextEngine.resolveContextFiles(phaseType);
757	      const prompt = await this.promptFactory.buildPrompt(phaseType, null, contextFiles);
758	
759	      return await runPhaseStepSession(
760	        prompt,
761	        PhaseStepType.Execute,
762	        this.config,
763	        sessionOpts,
764	        this.eventStream,
765	        { phase: phaseType, planName: planId },
766	      );
767	    } catch (err) {
768	      return {
769	        success: false,
770	        sessionId: '',
771	        totalCostUsd: 0,
772	        durationMs: 0,
773	        usage: { inputTokens: 0, outputTokens: 0, cacheReadInputTokens: 0, cacheCreationInputTokens: 0 },
774	        numTurns: 0,
775	        error: {
776	          subtype: 'error_during_execution',
777	          messages: [err instanceof Error ? err.message : String(err)],
778	        },
779	      };
780	    }
781	  }
782	
783	  /**
784	   * Run the verify step with full gap closure cycle.
785	   * Verification outcome routing:
786	   * - passed → proceed to advance
787	   * - human_needed → invoke onVerificationReview callback
788	   * - gaps_found → plan (create gap plans) → execute (run gap plans) → re-verify
789	   * Gap closure retries are capped at configurable maxGapRetries (default 1).
790	   */
791	  private async runVerifyStep(
792	    phaseNumber: string,
793	    sessionOpts: SessionOptions,
794	    callbacks: HumanGateCallbacks,
795	    options?: PhaseRunnerOptions,
796	  ): Promise<PhaseStepResult> {
797	    const stepStart = Date.now();
798	
799	    this.eventStream.emitEvent({
800	      type: GSDEventType.PhaseStepStart,
801	      timestamp: new Date().toISOString(),
802	      sessionId: '',
803	      phaseNumber,
804	      step: PhaseStepType.Verify,
805	    });
806	
807	    const maxGapRetries = options?.maxGapRetries ?? 1;
808	    let gapRetryCount = 0;
809	    let lastResult: PlanResult | undefined;
810	    let outcome: VerificationOutcome = 'passed';
811	    const allPlanResults: PlanResult[] = [];
812	
813	    while (true) {
814	      try {
815	        const phaseType = PhaseType.Verify;
816	        const contextFiles = await this.contextEngine.resolveContextFiles(phaseType);
817	        const prompt = await this.promptFactory.buildPrompt(phaseType, null, contextFiles);
818	
819	        lastResult = await runPhaseStepSession(
820	          prompt,
821	          PhaseStepType.Verify,
822	          this.config,
823	          sessionOpts,
824	          this.eventStream,
825	          { phase: phaseType },
826	        );
827	        allPlanResults.push(lastResult);
828	      } catch (err) {
829	        const durationMs = Date.now() - stepStart;
830	        const errorMsg = err instanceof Error ? err.message : String(err);
831	
832	        this.eventStream.emitEvent({
833	          type: GSDEventType.PhaseStepComplete,
834	          timestamp: new Date().toISOString(),
835	          sessionId: '',
836	          phaseNumber,
837	          step: PhaseStepType.Verify,
838	          success: false,
839	          durationMs,
840	          error: errorMsg,
841	        });
842	
843	        return {
844	          step: PhaseStepType.Verify,
845	          success: false,
846	          durationMs,
847	          error: errorMsg,
848	          planResults: allPlanResults.length > 0 ? allPlanResults : undefined,
849	        };
850	      }
851	
852	      // Parse verification outcome from session result
853	      outcome = this.parseVerificationOutcome(lastResult);
854	
855	      if (outcome === 'passed') {
856	        break;
857	      }
858	
859	      if (outcome === 'human_needed') {
860	        // Invoke verification review callback
861	        const decision = await this.invokeVerificationCallback(callbacks, phaseNumber, {
862	          step: PhaseStepType.Verify,
863	          success: lastResult.success,
864	          durationMs: Date.now() - stepStart,
865	          planResults: allPlanResults,
866	        });
867	
868	        if (decision === 'accept') {
869	          outcome = 'passed';
870	          break; // Treat as passed
871	        } else if (decision === 'retry' && gapRetryCount < maxGapRetries) {
872	          gapRetryCount++;
873	          continue;
874	        } else {
875	          // reject or exceeded retries
876	          const durationMs = Date.now() - stepStart;
877	          this.eventStream.emitEvent({
878	            type: GSDEventType.PhaseStepComplete,
879	            timestamp: new Date().toISOString(),
880	            sessionId: lastResult.sessionId,
881	            phaseNumber,
882	            step: PhaseStepType.Verify,
883	            success: false,
884	            durationMs,
885	            error: 'halted_by_callback',
886	          });
887	          return {
888	            step: PhaseStepType.Verify,
889	            success: false,
890	            durationMs,
891	            error: 'halted_by_callback',
892	            planResults: allPlanResults,
893	          };
894	        }
895	      }
896	
897	      if (outcome === 'gaps_found') {
898	        if (gapRetryCount < maxGapRetries) {
899	          gapRetryCount++;
900	          this.logger?.info(`Gap closure attempt ${gapRetryCount}/${maxGapRetries} for phase ${phaseNumber}`);
901	
902	          // ── Gap closure cycle: plan → execute → re-verify ──
903	
904	          // 1. Run a plan step to create gap plans
905	          try {
906	            const planResult = await this.runStep(PhaseStepType.Plan, phaseNumber, sessionOpts);
907	            if (planResult.planResults) {
908	              allPlanResults.push(...planResult.planResults);
909	            }
910	          } catch (err) {
911	            this.logger?.warn(`Gap closure plan step failed: ${err instanceof Error ? err.message : String(err)}`);
912	            // Proceed to re-verify anyway
913	          }
914	
915	          // 2. Re-query phase state to discover newly created gap plans
916	          try {
917	            await this.tools.initPhaseOp(phaseNumber);
918	          } catch (err) {
919	            this.logger?.warn(`Gap closure re-query failed, proceeding with stale state: ${err instanceof Error ? err.message : String(err)}`);
920	          }
921	
922	          // 3. Execute gap plans via the wave-capable runExecuteStep
923	          try {
924	            const executeResult = await this.runExecuteStep(phaseNumber, sessionOpts);
925	            if (executeResult.planResults) {
926	              allPlanResults.push(...executeResult.planResults);
927	            }
928	          } catch (err) {
929	            this.logger?.warn(`Gap closure execute step failed: ${err instanceof Error ? err.message : String(err)}`);
930	            // Proceed to re-verify anyway
931	          }
932	
933	          // 4. Continue the loop to re-verify
934	          continue;
935	        }
936	        // Exceeded gap closure retries — proceed
937	        break;
938	      }
939	
940	      break; // Safety: unknown outcome → proceed
941	    }
942	
943	    const durationMs = Date.now() - stepStart;
944	    const verifySuccess = outcome === 'passed';
945	
946	    this.eventStream.emitEvent({
947	      type: GSDEventType.PhaseStepComplete,
948	      timestamp: new Date().toISOString(),
949	      sessionId: lastResult?.sessionId ?? '',
950	      phaseNumber,
951	      step: PhaseStepType.Verify,
952	      success: verifySuccess,
953	      durationMs,
954	      ...(!verifySuccess && { error: `verification_${outcome}` }),
955	    });
956	
957	    return {
958	      step: PhaseStepType.Verify,
959	      success: verifySuccess,
960	      durationMs,
961	      planResults: allPlanResults,
962	      ...(!verifySuccess && { error: `verification_${outcome}` }),
963	    };
964	  }
965	
966	  /**
967	   * Run the advance step — mark phase complete.
968	   * Gated by config.workflow.auto_advance or callback approval.
969	   */
970	  private async runAdvanceStep(
971	    phaseNumber: string,
972	    _sessionOpts: SessionOptions,
973	    callbacks: HumanGateCallbacks,
974	  ): Promise<PhaseStepResult> {
975	    const stepStart = Date.now();
976	
977	    this.eventStream.emitEvent({
978	      type: GSDEventType.PhaseStepStart,
979	      timestamp: new Date().toISOString(),
980	      sessionId: '',
981	      phaseNumber,
982	      step: PhaseStepType.Advance,
983	    });
984	
985	    // Check if auto_advance or callback approves
986	    let shouldAdvance = this.config.workflow.auto_advance;
987	
988	    if (!shouldAdvance && callbacks.onBlockerDecision) {
989	      try {
990	        const decision = await callbacks.onBlockerDecision({
991	          phaseNumber,
992	          step: PhaseStepType.Advance,
993	          error: undefined,
994	        });
995	        shouldAdvance = decision !== 'stop';
996	      } catch (err) {
997	        this.logger?.warn(`Advance callback threw, auto-approving: ${err instanceof Error ? err.message : String(err)}`);
998	        shouldAdvance = true; // Auto-approve on callback error
999	      }
1000	    } else if (!shouldAdvance) {
1001	      // No callback, auto-approve
1002	      shouldAdvance = true;
1003	    }
1004	
1005	    if (!shouldAdvance) {
1006	      const durationMs = Date.now() - stepStart;
1007	      this.eventStream.emitEvent({
1008	        type: GSDEventType.PhaseStepComplete,
1009	        timestamp: new Date().toISOString(),
1010	        sessionId: '',
1011	        phaseNumber,
1012	        step: PhaseStepType.Advance,
1013	        success: false,
1014	        durationMs,
1015	        error: 'advance_rejected',
1016	      });
1017	      return {
1018	        step: PhaseStepType.Advance,
1019	        success: false,
1020	        durationMs,
1021	        error: 'advance_rejected',
1022	      };
1023	    }
1024	
1025	    try {
1026	      await this.tools.phaseComplete(phaseNumber);
1027	    } catch (err) {
1028	      const durationMs = Date.now() - stepStart;
1029	      const errorMsg = err instanceof Error ? err.message : String(err);
1030	
1031	      this.eventStream.emitEvent({
1032	        type: GSDEventType.PhaseStepComplete,
1033	        timestamp: new Date().toISOString(),
1034	        sessionId: '',
1035	        phaseNumber,
1036	        step: PhaseStepType.Advance,
1037	        success: false,
1038	        durationMs,
1039	        error: errorMsg,
1040	      });
1041	
1042	      return {
1043	        step: PhaseStepType.Advance,
1044	        success: false,
1045	        durationMs,
1046	        error: errorMsg,
1047	      };
1048	    }
1049	
1050	    const durationMs = Date.now() - stepStart;
1051	
1052	    this.eventStream.emitEvent({
1053	      type: GSDEventType.PhaseStepComplete,
1054	      timestamp: new Date().toISOString(),
1055	      sessionId: '',
1056	      phaseNumber,
1057	      step: PhaseStepType.Advance,
1058	      success: true,
1059	      durationMs,
1060	    });
1061	
1062	    return {
1063	      step: PhaseStepType.Advance,
1064	      success: true,
1065	      durationMs,
1066	    };
1067	  }
1068	
1069	  // ─── Helpers ───────────────────────────────────────────────────────────
1070	
1071	  /**
1072	   * Map PhaseStepType to PhaseType for prompt/context resolution.
1073	   */
1074	  private stepToPhaseType(step: PhaseStepType): PhaseType {
1075	    const mapping: Record<string, PhaseType> = {
1076	      [PhaseStepType.Discuss]: PhaseType.Discuss,
1077	      [PhaseStepType.Research]: PhaseType.Research,
1078	      [PhaseStepType.Plan]: PhaseType.Plan,
1079	      [PhaseStepType.PlanCheck]: PhaseType.Verify,
1080	      [PhaseStepType.Execute]: PhaseType.Execute,
1081	      [PhaseStepType.Verify]: PhaseType.Verify,
1082	    };
1083	    return mapping[step] ?? PhaseType.Execute;
1084	  }
1085	
1086	  /**
1087	   * Parse the verification outcome from a PlanResult.
1088	   * In a real implementation, this would parse the session output for
1089	   * structured verification signals. For now, map from success/error.
1090	   */
1091	  private parseVerificationOutcome(result: PlanResult): VerificationOutcome {
1092	    if (result.success) return 'passed';
1093	    if (result.error?.subtype === 'human_review_needed') return 'human_needed';
1094	    return 'gaps_found';
1095	  }
1096	
1097	  /**
1098	   * Check RESEARCH.md for unresolved open questions (#1602).
1099	   * Returns the gate result — pass means safe to proceed to planning.
1100	   */
1101	  private async checkResearchGate(phaseOp: PhaseOpInfo): Promise<{ pass: boolean; unresolvedQuestions: string[] }> {
1102	    try {
1103	      const researchPath = phaseOp.research_path ||
1104	        join(phaseOp.phase_dir, `${phaseOp.padded_phase}-RESEARCH.md`);
1105	      const content = await readFile(researchPath, 'utf-8');
1106	      return checkResearchGate(content);
1107	    } catch {
1108	      // File doesn't exist or can't be read — pass (nothing to gate on)
1109	      return { pass: true, unresolvedQuestions: [] };
1110	    }
1111	  }
1112	
1113	  /**
1114	   * Invoke the onBlockerDecision callback, falling back to auto-approve.
1115	   */
1116	  private async invokeBlockerCallback(
1117	    callbacks: HumanGateCallbacks,
1118	    phaseNumber: string,
1119	    step: PhaseStepType,
1120	    error?: string,
1121	  ): Promise<'retry' | 'skip' | 'stop'> {
1122	    if (!callbacks.onBlockerDecision) {
1123	      return 'skip'; // Auto-approve: skip the blocker
1124	    }
1125	
1126	    try {
1127	      const decision = await callbacks.onBlockerDecision({ phaseNumber, step, error });
1128	      // Validate return value
1129	      if (decision === 'retry' || decision === 'skip' || decision === 'stop') {
1130	        return decision;
1131	      }
1132	      this.logger?.warn(`Unexpected blocker callback return value: ${String(decision)}, falling back to skip`);
1133	      return 'skip';
1134	    } catch (err) {
1135	      this.logger?.warn(`Blocker callback threw, auto-approving: ${err instanceof Error ? err.message : String(err)}`);
1136	      return 'skip'; // Auto-approve on error
1137	    }
1138	  }
1139	
1140	  /**
1141	   * Invoke the onVerificationReview callback, falling back to auto-accept.
1142	   */
1143	  private async invokeVerificationCallback(
1144	    callbacks: HumanGateCallbacks,
1145	    phaseNumber: string,
1146	    stepResult: PhaseStepResult,
1147	  ): Promise<'accept' | 'reject' | 'retry'> {
1148	    if (!callbacks.onVerificationReview) {
1149	      return 'accept'; // Auto-approve
1150	    }
1151	
1152	    try {
1153	      const decision = await callbacks.onVerificationReview({ phaseNumber, stepResult });
1154	      if (decision === 'accept' || decision === 'reject' || decision === 'retry') {
1155	        return decision;
1156	      }
1157	      this.logger?.warn(`Unexpected verification callback return value: ${String(decision)}, falling back to accept`);
1158	      return 'accept';
1159	    } catch (err) {
1160	      this.logger?.warn(`Verification callback threw, auto-accepting: ${err instanceof Error ? err.message : String(err)}`);
1161	      return 'accept'; // Auto-approve on error
1162	    }
1163	  }
1164	}
